function openActionDialog(id){const d=$(id);if(d.open||d.hasAttribute('open'))return;d.setAttribute('role','dialog');d.setAttribute('aria-modal','true');if(typeof d.showModal==='function')d.showModal();else{d.setAttribute('open','');d.classList.add('dialog-fallback')}}
