function chooseIndependent(){customerSelection={kind:'independent'};$('orderCustomerId').value=operationId();closeActionDialog('customerMatchDialog');showMatches()}
function chooseExisting(c,preserveContact){const platform=$('contact').value,account=$('contactAccount').value,suffix=$('customerPhoneLast3').value;const mismatch=!!(suffix&&c.phoneLast3&&suffix!==c.phoneLast3);if(mismatch&&!confirm('手機後三碼不同，預設應建立獨立客戶。已核對確定是同一人嗎？確認後只關聯新訂單，保留舊客戶原後三碼。'))return;fillCustomer(c);if(preserveContact){$('contact').value=platform;$('contactAccount').value=account;if(suffix)$('customerPhoneLast3').value=suffix}customerSelection={kind:'existing',id:c.id,snapshot:JSON.parse(JSON.stringify(c)),allowSuffixMismatch:mismatch};closeActionDialog('customerMatchDialog');showMatches()}
