 if(found.length&&!customerSelection&&!$('oid').value){const button=document.createElement('button');button.type='button';button.textContent='確認可能符合的客戶';button.onclick=()=>showCustomerCandidates(found);$('customerMatch').append(button);const preview=document.createElement('div');preview.className='candidate-summary';preview.innerHTML=found.map(c=>'<article class="card"><b>'+esc(c.name)+' '+esc(c.phoneLast3||'未記錄後三碼')+'</b><p>管道：'+esc(c.channels.map(x=>x.platform+' '+x.account).join('、'))+'<br>'+c.count+' 筆 · '+money(c.total)+' · 最近 '+esc(dateText(c.last))+'</p><details><summary>購買紀錄</summary>'+c.orders.map(o=>'<p>訂單 '+esc(o.id)+' · '+esc(dateText(o.createdAt))+' · '+money(C.total(o))+'<br>'+esc(C.items(o).map(i=>(i.productName||'未填商品名')+' × '+(+i.qty||0)+'（贈 '+(+i.gift||0)+'）').join('、'))+'</p>').join('')+'</details></article>').join('');$('customerMatch').append(preview);}
