 const isNew=!$('oid').value,draft=orderDraft;if(!draft)throw Error('請重新開啟訂單');const id=draft.id,old=isNew?null:editingSnapshot;
 if(isNew&&orders[id]&&management.inventoryOperations?.[draft.operation]){draft.completed=true;throw Error('此筆訂單已儲存，請關閉後從訂單清單查看；不要重複建立')}
