 let customerId=$('orderCustomerId').value;if(isNew&&!customerSelection&&matches().length){showCustomerCandidates(matches());throw Error('請先確認使用舊客戶或建立獨立客戶')}if(!customerId)customerId=operationId();
 const data={...(old||{}),customer:name,...(isNew?{customerId}:C.hasOwn(old||{},'customerId')?{customerId:old.customerId}:{}),...(isNew||suffix?{phoneLast3:suffix,phoneLast3Pending:!suffix}:{}),phone:$('customerPhone').value.trim(),contactType:$('contact').value,contactOther:$('contactAccount').value.trim(),items,amount:items.reduce((s,i)=>s+i.qty*i.unitPrice,0),delivery,deliveryDetail:delivery==='面交'?($('pickupPlace').value==='其他'?$('pickupOther').value.trim():$('pickupPlace').value):$('deliveryLocation').value.trim(),notes:$('notes').value,shipped:$('shipped').value==='1',paid,updatedAt:firebase.database.ServerValue.TIMESTAMP,updatedBy:op};
 const currentFields=orderFieldValues();if(old)for(const key of Object.keys(currentFields)){if(currentFields[key]===draft.initialFields[key]){if(C.hasOwn(old,key))data[key]=JSON.parse(JSON.stringify(old[key]));else delete data[key]}}if(old&&currentFields.phoneLast3===draft.initialFields.phoneLast3){if(C.hasOwn(old,'phoneLast3Pending'))data.phoneLast3Pending=old.phoneLast3Pending;else delete data.phoneLast3Pending}
