 if(isNew)data.createdAt=firebase.database.ServerValue.TIMESTAMP;
 if(old&&currentFields.paid===draft.initialFields.paid){if(C.hasOwn(old,'paidAt'))data.paidAt=JSON.parse(JSON.stringify(old.paidAt));else delete data.paidAt}else{if(paid&&!old?.paid)data.paidAt=firebase.database.ServerValue.TIMESTAMP;if(!paid)delete data.paidAt;}
 await saveOrder(id,data,old,isNew?(customerSelection||{kind:'new'}):undefined,draft.operation);draft.completed=true;closeActionDialog('od');
