function resetInventoryReceipt(id,expected){inventoryDraft={id:id||operationId(),operation:operationId(),expected:expected?JSON.parse(JSON.stringify(expected)):null};inventoryPending=null;$('inventoryReceipt').reset();$('receiptTitle').textContent=id?'編輯製作／入庫':'新增製作／入庫';$('receiptDate').value=expected?.date||localDate();$('receiptType').value=expected?.kind||'production';$('receiptNotes').value=expected?.notes||'';$('receiptLines').textContent='';for(const line of Object.values(expected?.lines||{one:{}}))receiptLine(line);inventoryInitial=formSnapshot($('inventoryReceipt'))}
