let financeView='home',purchaseBaseline='',shrimpBaseline='',financeRoute={page:'orders',view:'home',index:0},restoringFinanceHistory=false;
const financePanels={};
const expensePanel=$('panel-expenses'),purchaseForm=$('expenseForm'),costForm=$('shrimpForm');
const categoryCard=$('categorySelect').parentElement,expenseFilters=$('expenseSearch').parentElement,shrimpFilters=$('shrimpSearch').parentElement;
const expenseList=$('expenseList'),shrimpList=$('shrimpList'),operations=$('financeOperations'),expenseExport=$('exportExpenses'),shrimpExport=$('exportShrimp');
expenseExport.remove();shrimpExport.remove();
expensePanel.textContent='';
expensePanel.innerHTML='<div id="financeNotice" role="status" class="management-help"></div>';
for(const [id,title] of [['home','料理包支出'],['purchase','新增支出'],['shrimp','蝦子製作成本'],['records','支出紀錄'],['detail','支出明細'],['more','更多功能']]){
 const s=document.createElement('section');s.className='finance-view'+(id==='home'?'':' hidden');s.id='finance-'+id;
 s.innerHTML='<header class="finance-heading">'+(id==='home'?'':'<button type="button" data-finance-back aria-label="返回支出首頁">‹ 返回</button>')+'<h2>'+title+'</h2>'+(id==='home'?'<button type="button" data-finance-go="more">更多功能</button>':'')+'</header>';expensePanel.append(s);financePanels[id]=s;
}
financePanels.home.insertAdjacentHTML('beforeend','<label class="finance-month">統計月份<input id="expenseMonth" type="month" value="'+localDate().slice(0,7)+'"></label><div id="expenseHomeStats" class="finance-home-stats"></div><p id="expenseHomeWarnings" class="management-help"></p><div class="finance-actions"><button type="button" class="primary" id="financeNewExpense">＋ 新增支出</button><button type="button" data-finance-go="shrimp">蝦子成本</button><button type="button" data-finance-go="records">支出紀錄</button></div><h3>最近支出</h3><div id="recentExpenses"></div>');
financePanels.purchase.append(purchaseForm);purchaseForm.querySelector('h3').textContent='採購／營運記帳';
financePanels.shrimp.append(costForm,shrimpFilters,shrimpList);financePanels.shrimp.insertAdjacentHTML('beforeend','<p class="management-help">自養蝦估算不是付款，請勿另建同筆採購；外購蝦需關聯原採購，不再次扣成本。1 台斤＝600 公克。</p>');
financePanels.records.append(expenseFilters,expenseList);expenseFilters.insertAdjacentHTML('beforeend','<label>分類<select id="expenseCategoryFilter"><option value="">全部分類</option></select></label>');
financePanels.detail.insertAdjacentHTML('beforeend','<div id="expenseDetails"></div>');
financePanels.more.append(categoryCard);financePanels.more.insertAdjacentHTML('beforeend','<div id="financeExports" class="card"><h3>CSV 匯出</h3><p class="management-help">依支出紀錄／蝦子成本目前篩選匯出。報表匯出位於營業報表。</p></div>');$('financeExports').append(expenseExport,shrimpExport);financePanels.more.insertAdjacentHTML('beforeend','<h3>財務操作紀錄</h3>');financePanels.more.append(operations);
// Normal-flow actions never float over a keyboard or input.
for(const form of [purchaseForm,costForm]){const actions=document.createElement('div');actions.className='finance-form-actions';actions.append(form.querySelector('button.primary'),form.querySelector(form===purchaseForm?'#cancelExpense':'#cancelShrimp'));form.append(actions)}

function formSnapshot(form){return JSON.stringify([...form.querySelectorAll('input,select,textarea')].map(e=>[e.id||e.dataset.field||'confirmation',e.type==='checkbox'?e.checked:e.value]))}
function financeDirty(){return financeView==='purchase'&&!financeDraft?.completed&&formSnapshot(purchaseForm)!==purchaseBaseline||financeView==='shrimp'&&!shrimpDraft?.completed&&formSnapshot(costForm)!==shrimpBaseline}
function allowFinanceLeave(){if(!allowInventoryLeave())return false;if(busy){fail(Error('操作尚未完成，請稍候並確認結果'));return false}if(!financeDirty())return true;if(!confirm('尚有未儲存內容，確定放棄並離開？'))return false;if(financeView==='purchase')resetExpense();else resetShrimp();return true}
function renderFinanceView(view){financeView=view;for(const [key,panel] of Object.entries(financePanels))panel.classList.toggle('hidden',key!==view);expensePanel.dataset.financeView=view;renderExpenseHome()}
function applyFinanceRoute(route){if(route.page!=='inventory'&&inventoryView!=='home'){inventoryView='home';inventoryDraft=null;inventoryPending=null;inventoryNavigate('home',true)}financeRoute=route;document.querySelectorAll('.management-panel').forEach(p=>p.classList.toggle('hidden',p.id!=='panel-'+route.page));document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.page===route.page)));renderFinanceView(route.view||'home');refreshManagement();window.scrollTo(0,0)}
function financeNavigate(view='home',force=false,page='expenses',replace=false){if(!force&&!allowFinanceLeave())return false;const route={page,view,index:replace?financeRoute.index:financeRoute.index+1};try{history[replace?'replaceState':'pushState']({...history.state,shrimpFinance:route},'',page==='expenses'?'#expenses/'+view:location.pathname+location.search)}catch(_){}applyFinanceRoute(route);return true}
function resetFinanceNavigation(){if(typeof financePanels==='undefined')return;financeView='home';purchaseBaseline=formSnapshot(purchaseForm);shrimpBaseline=formSnapshot(costForm);financeRoute={page:'orders',view:'home',index:Number.isInteger(history.state?.shrimpFinance?.index)?history.state.shrimpFinance.index:0};try{history.replaceState({...history.state,shrimpFinance:financeRoute},'',location.pathname+location.search)}catch(_){}applyFinanceRoute(financeRoute)}
window.addEventListener('popstate',e=>{
 if(restoringFinanceHistory){restoringFinanceHistory=false;return}const target=e.state?.shrimpFinance||{page:'orders',view:'home',index:0};
 if(!allowFinanceLeave()){const delta=financeRoute.index-target.index;if(delta){restoringFinanceHistory=true;history.go(delta)}else try{history.replaceState({...history.state,shrimpFinance:financeRoute},'','#expenses/'+financeView)}catch(_){}return}applyFinanceRoute(target);
});
window.addEventListener('beforeunload',e=>{if(busy||financeDirty()||inventoryDirty()){e.preventDefault();e.returnValue=''}});
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>financeNavigate('home',false,b.dataset.page));
expensePanel.querySelectorAll('[data-finance-go]').forEach(b=>b.onclick=()=>financeNavigate(b.dataset.financeGo));
expensePanel.querySelectorAll('[data-finance-back]').forEach(b=>b.onclick=()=>financeNavigate('home'));
$('financeNewExpense').onclick=()=>{if(!allowFinanceLeave())return;resetExpense();financeNavigate('purchase',true)};

const resetExpenseBeforeMobile=resetExpense;resetExpense=function(){resetExpenseBeforeMobile();financeDraft.lastMode=$('expenseMode').value;financeDraft.detailedReady=false;financePanels.purchase.querySelector('header h2').textContent='新增支出';purchaseBaseline=formSnapshot(purchaseForm)};
const resetShrimpBeforeMobile=resetShrimp;resetShrimp=function(){resetShrimpBeforeMobile();shrimpBaseline=formSnapshot(costForm)};
$('cancelExpense').onclick=()=>{if(allowFinanceLeave()){resetExpense();financeNavigate('home',true)}};
$('cancelShrimp').onclick=()=>{if(allowFinanceLeave()){resetShrimp();financeNavigate('home',true)}};
$('expenseMode').onchange=()=>{
 const to=$('expenseMode').value,from=financeDraft.lastMode||'simple';if(to==='simple'&&from==='detailed'&&$('purchaseLines').children.length>1&&!confirm('改成簡單記帳後，本次儲存不保留多品項明細。確定切換？')){$('expenseMode').value='detailed';return}
 if(to==='detailed'&&!financeDraft.detailedReady){$('purchaseLines').textContent='';const amount=$('expenseAmount').value;let cents;try{if(amount)cents=C.scaled(amount,2)}catch(_){}addPurchaseLine({name:$('expenseTitle').value,categoryId:$('expenseCategory').value,subtotalCents:cents,amountBasis:amount?'manual':'calculated',shrimp:$('simpleShrimp').checked,weightMilliCatty:$('simpleWeight').value?Number($('simpleWeight').value)*1000:0},financeDraft.lineId);financeDraft.detailedReady=true;}
 if(to==='simple'&&from==='detailed'){try{const data={...purchaseDraftData(),mode:'detailed'},rows=[...$('purchaseLines').children];let sum=0;for(const row of rows)sum+=C.scaled(row.querySelector('[data-field="amount"]').value,2);$('expenseAmount').value=(sum/100).toFixed(2);$('expenseTitle').value=rows.length===1?rows[0].querySelector('[data-field="name"]').value:'多品項採購';if(rows[0])$('expenseCategory').value=rows[0].querySelector('[data-field="categoryId"]').value;}catch(_){} }
 financeDraft.lastMode=to;expenseMode();
};
const editExpenseBeforeMobile=editExpense;editExpense=function(entry){if(!allowFinanceLeave())return;const current=C.financeEntries(management.expenses||{},financeState()).find(p=>p.id===entry.id);if(!current){fail(Error('此支出已移除或尚未同步，請重新查看'));return}if(!C.equalLegacy(entry,current)){showExpenseDetail(current);fail(Error('此支出已被其他裝置更新，請核對最新明細後再按編輯'));return}if(editExpenseBeforeMobile(entry)!==true)return;financeDraft.detailedReady=$('expenseMode').value==='detailed';financeDraft.lastMode=$('expenseMode').value;purchaseBaseline=formSnapshot(purchaseForm);financePanels.purchase.querySelector('header h2').textContent='編輯支出';financeNavigate('purchase',true)};
function openShrimpEditor(){shrimpBaseline=formSnapshot(costForm);financeNavigate('shrimp',true)}
function financeSaved(kind){$('financeNotice').textContent=kind==='purchase'?'支出已儲存':'蝦子製作成本已儲存';financeNavigate('home',true)}

const visibleExpensesBeforeMobile=visibleExpenses;visibleExpenses=function(){const category=$('expenseCategoryFilter')?.value;return visibleExpensesBeforeMobile().filter(p=>!category||Object.values(p.items||{}).some(l=>l.categoryId===category))};
function monthRange(value){if(!/^\d{4}-\d{2}$/.test(value)||!C.validDate(value+'-01'))throw Error('請選擇有效月份');const [y,m]=value.split('-').map(Number);return [value+'-01',localDate(new Date(Date.UTC(y,m,0,4)))];}
function renderExpenseHome(){if(!$('expenseMonth'))return;try{const [start,end]=monthRange($('expenseMonth').value),r=C.financeReport({},management.expenses||{},financeState(),start,end),entries=C.financeEntries(management.expenses||{},financeState()).filter(p=>p.status!=='void'&&p.scope==='mealPacks'&&C.validDate(p.purchaseDate)&&p.purchaseDate>=start&&p.purchaseDate<=end).sort((a,b)=>String(b.purchaseDate).localeCompare(String(a.purchaseDate))||b.id.localeCompare(a.id));$('expenseHomeStats').innerHTML=[['已付支出',financeMoney(r.D),'依付款日'],['未付款金額',financeMoney(r.purchaseUnpaid),'本月採購、目前未付'],['記帳筆數',entries.length,'依採購日，排除作廢']].map(([k,v,n])=>'<article class="card"><span>'+k+'</span><strong>'+v+'</strong><small>'+n+'</small></article>').join('');$('expenseHomeWarnings').textContent='付款狀態不明 '+financeMoney(r.purchaseUnknown)+'；全期已付但付款日期不明 '+r.unknownExpensePayments+' 筆；待核對 '+r.invalidExpenses+' 筆。自養蝦估算不列現金支出。';$('recentExpenses').innerHTML=entries.slice(0,5).map((p,n)=>'<button type="button" class="finance-recent" data-recent="'+n+'"><span>'+esc(Object.values(p.items||{}).map(l=>l.name).join('、'))+'</span><strong>'+(p.totalCents==null?'金額待核對':financeMoney(p.totalCents/100))+'</strong><small>'+esc(p.purchaseDate)+' · '+esc(({paid:'已付款',unpaid:'未付款',unknown:'付款不明'})[p.payment?.status]||'付款不明')+'</small></button>').join('')||'<p class="management-help">本月尚無支出，可按「新增支出」記帳。</p>';$('recentExpenses').querySelectorAll('[data-recent]').forEach(b=>b.onclick=()=>showExpenseDetail(entries[+b.dataset.recent]));}catch(e){$('expenseHomeStats').textContent=e.message;$('recentExpenses').textContent=''}}
$('expenseMonth').onchange=renderExpenseHome;
function showExpenseDetail(p){if(!allowFinanceLeave())return;const lines=Object.values(p.items||{});$('expenseDetails').innerHTML='<article class="card"><h3>'+esc(lines.map(l=>l.name).join('、'))+'</h3><p>'+esc(p.purchaseDate||'日期不明')+' · '+esc(p.id)+' · '+esc(p.status)+'</p>'+lines.map(l=>'<div class="expense-detail-line"><b>'+esc(l.name)+'</b><p>'+esc(categoryMap()[l.categoryId]?.name||l.category||'未分類')+' · '+(l.subtotalCents==null?'待核對':financeMoney(l.subtotalCents/100))+'</p><p>數量 '+esc(l.quantityMilli==null?'未填':l.quantityMilli/1000)+' '+esc(l.unit||'')+'／單價 '+(l.unitPriceCents==null?'未填':financeMoney(l.unitPriceCents/100))+'</p>'+(l.calculatedSubtotalCents==null?'':'<p>計算小計 '+financeMoney(l.calculatedSubtotalCents/100)+(l.differenceConfirmedFor?' · 已確認採用手動金額':'')+'</p>')+'<p>'+esc(l.notes||'')+'</p></div>').join('')+'<p>自付採購運費 '+financeMoney((p.shippingCents||0)/100)+'</p><p>總額 '+(p.totalCents==null?'待核對':financeMoney(p.totalCents/100))+'</p><p>付款 '+esc(({paid:'已付款',unpaid:'未付款',unknown:'付款不明'})[p.payment?.status]||'付款不明')+' · '+esc(p.payment?.paidDate||'付款日期未記錄')+'</p><p>商家 '+esc(p.merchant||'未填')+'</p><p>'+esc(p.notes||'')+'</p><button type="button" id="financeDetailEdit">編輯支出</button></article>';$('financeDetailEdit').onclick=()=>editExpense(p);financeNavigate('detail',true)}
const renderExpensesBeforeMobile=renderExpenses;renderExpenses=function(){renderExpensesBeforeMobile();const filter=$('expenseCategoryFilter'),v=filter.value;filter.innerHTML='<option value="">全部分類</option>'+categoryOptions(v,true);filter.value=v;const entries=visibleExpenses();$('expenseList').querySelectorAll('[data-expense]').forEach(b=>{const p=entries[+b.dataset.expense],detail=document.createElement('button');detail.type='button';detail.textContent='查看';detail.onclick=()=>showExpenseDetail(p);b.parentElement.append(detail)});renderExpenseHome()};
$('expenseCategoryFilter').onchange=renderExpenses;
resetExpense();resetShrimp();renderFinanceView('home');


// Cancellation and returns preserve original order snapshots and payment fields.
function decorateInventoryOrders(){const inv=management.inventory||{};const pending={};for(const [id,o] of Object.entries(orders))if(!o.shipped&&!inv.orderStates?.[id]?.cancelled)for(const i of C.items(o)){const row=pending[i.productId]||={name:i.productName,n:0};row.n+=(+i.qty||0)+(+i.gift||0)}$('pending').innerHTML=Object.values(pending).map(p=>'<span>'+esc(p.name)+'｜未出貨 <b>'+p.n+'</b> 包</span>').join('')||'目前沒有未出貨品項';for(const card of $('rows').querySelectorAll('.order-card')){const id=card.querySelector('button')?.getAttribute('onclick')?.match(/\x27([^\x27]+)\x27/)?.[1];if(!id||!orders[id])continue;const o=orders[id],state=inv.orderStates?.[id]||null,actions=card.querySelector('.card-actions');if(state?.cancelled){const p=document.createElement('p');p.className='danger';p.textContent='已取消（保留原訂單及收款；不自動退款）';card.append(p)}const remove=actions.querySelector('.danger');if(remove&&(o.shipped||inv.everShipped?.[id]||state)){remove.disabled=true;remove.textContent='歷史保留'}
 const cancel=document.createElement('button');cancel.type='button';cancel.textContent=state?.cancelled?'恢復接單':'取消訂單';cancel.onclick=()=>{if(!confirm(state?.cancelled?'確認恢復接單？不會自動出貨或改動收款。':'確認取消訂單？不刪除、不退款、不自動回補庫存；實際退回請另做退貨入庫。'))return;const key=operationId();guard(()=>writeInventory({kind:state?.cancelled?'reopen':'cancel',orderId:id,expected:o,expectedState:state,reason:'使用者確認'},key))};actions.append(cancel);
 if(o.shipped){const ret=document.createElement('button');ret.type='button';ret.textContent='退貨入庫';ret.onclick=()=>{try{openInventoryReturn(id)}catch(e){fail(e)}};actions.append(ret);const returned=inv.returned?.[id];if(returned){const p=document.createElement('p');p.textContent='已確認回庫 '+Object.values(returned).reduce((s,n)=>s+n,0)+' 包（原出貨與收款紀錄保留）';card.append(p)}}
 }}
$('app').insertAdjacentHTML('beforeend','<dialog id="inventoryReturnDialog"><form id="inventoryReturnForm"><h2>退貨確認入庫</h2><p>只填已實際放回冷凍庫且可再販售的包數。不可販售商品不加入現貨；此操作不代表退款。</p><div id="inventoryReturnLines"></div><label><input type="checkbox" id="inventoryReturnConfirmed" required>確認上述商品已實際回庫且可再販售</label><label>原因／備註<textarea id="inventoryReturnReason"></textarea></label><div class="inventory-form-actions"><button class="primary">確認退貨入庫</button><button type="button" id="inventoryReturnClose">取消</button></div></form></dialog>');
let inventoryReturnDraft=null;
function openInventoryReturn(id){const order=orders[id];if(!order?.shipped)return;const returned=management.inventory?.returned?.[id]||{};inventoryReturnDraft={orderId:id,expected:JSON.parse(JSON.stringify(order)),expectedState:management.inventory?.orderStates?.[id]?JSON.parse(JSON.stringify(management.inventory.orderStates[id])):null,expectedReturned:JSON.parse(JSON.stringify(returned)),operation:operationId()};$('inventoryReturnForm').reset();$('inventoryReturnLines').innerHTML=Object.entries(C.quantities(order)).map(([pid,n])=>'<label>'+esc(C.items(order).find(i=>i.productId===pid)?.productName||pid)+'（可退 '+(n-(returned[pid]||0))+' 包）<input data-return-product="'+esc(pid)+'" type="number" min="0" max="'+(n-(returned[pid]||0))+'" step="1" value="0"></label>').join('');openActionDialog('inventoryReturnDialog')}
$('inventoryReturnClose').onclick=()=>{if(!busy){closeActionDialog('inventoryReturnDialog');inventoryReturnDraft=null}};
$('inventoryReturnForm').onsubmit=e=>{e.preventDefault();guard(async()=>{const d=inventoryReturnDraft;if(!d)throw Error('請重新開啟退貨視窗');const quantities=Object.fromEntries([...document.querySelectorAll('[data-return-product]')].map(x=>[x.dataset.returnProduct,x.value]));await writeInventory({kind:'return',orderId:d.orderId,expected:d.expected,expectedState:d.expectedState,expectedReturned:d.expectedReturned,quantities,confirmed:$('inventoryReturnConfirmed').checked,reason:$('inventoryReturnReason').value},d.operation);closeActionDialog('inventoryReturnDialog');inventoryReturnDraft=null;$('inventoryNotice').textContent='退貨入庫已儲存；訂單金額與收款未改動'})};

function sessionFailure(e,stage){window.reportScriptFailure(e,{file:'management.js',stage});fail(e)}
window.addEventListener('unhandledrejection',e=>sessionFailure(e.reason,'非同步操作'));
// Catch application callback errors here, before the cross-origin SDK can rethrow them.
auth.onAuthStateChanged(u=>{startOrderSession(u).catch(e=>sessionFailure(e,'Firebase 登入狀態初始化'))},e=>sessionFailure(e,'Firebase Authentication'));


for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault()});
function fitDialogsToViewport(){const v=window.visualViewport;document.documentElement.style.setProperty('--shrimp-dialog-height',Math.max(80,(v?v.height:window.innerHeight)-24)+'px');document.documentElement.style.setProperty('--shrimp-dialog-top',(Math.max(0,v?v.offsetTop:0)+12)+'px')}
window.addEventListener('resize',fitDialogsToViewport);if(window.visualViewport){window.visualViewport.addEventListener('resize',fitDialogsToViewport);window.visualViewport.addEventListener('scroll',fitDialogsToViewport)}fitDialogsToViewport();
